std::vector<std::string> remaining(const GameApplication& game){std::vector<std::string> ids;for(const auto& [id,e]:game.content().enemies){if(e.map==game.mapId()&&!game.session().flag(e.deadFlag)){ids.push_back(id);}}return ids;}

void corridorFight(G2NaturalDriver& r){
 r.equip(20);int fired=0,wait=0;
 for(int n=0;n<20000;++n){auto& g=r.game;auto& state=g.session();need(state.hp()>0&&g.mode()==ApplicationMode::Playing,"Actual corridor battle died");auto alive=remaining(g);if(alive.empty()){r.lower();std::cout<<"G6-03 real corridor battle shots="<<fired<<" HP="<<state.hp()<<'\n';return;}InputFrame in;const int weapon=state.equipped(1),ammo=state.magazine(weapon);
  if(g.foreground()!=ForegroundKind::None||g.dialogue().active()){if(n%8==0){in=key();}}
  else if(state.flag(10)){in=key(InputAction::Up);}
  else if(wait){--wait;}
  else if(!g.raised()){in=key(InputAction::Weapon);}
  else{for(const auto& e:g.enemyStates()){if(e.mode==EnemyMode::Ending||e.mode==EnemyMode::Corpse||e.mode==EnemyMode::Fallen){std::erase(alive,e.id);}}if(alive.empty()){r.tick();continue;}const auto pos=g.world().player().motion.tile();const auto target=*std::min_element(alive.begin(),alive.end(),[&](const auto& a,const auto& b){auto x=findCharacter(g.world(),a).motion.tile(),y=findCharacter(g.world(),b).motion.tile();return std::abs(x.x-pos.x)+std::abs(x.y-pos.y)<std::abs(y.x-pos.x)+std::abs(y.y-pos.y);});const auto tile=findCharacter(g.world(),target).motion.tile();const int dx=tile.x-pos.x,dy=tile.y-pos.y;const Direction facing=std::abs(dx)>std::abs(dy)?(dx>0?Direction::Right:Direction::Left):(dy>0?Direction::Down:Direction::Up);
   if((dx&&dy)||std::abs(dx)+std::abs(dy)>1){for(Direction side:{Direction::Down,Direction::Up,Direction::Right,Direction::Left}){if(auto step=next(g.world(),adjacentTile(tile,side))){in.movement=step;break;}}}
   else if(g.world().player().motion.facing()!=facing){in.buttons[int(InputAction::Weapon)].held=true;in.movement=facing;}
   else if(n%12==0){need(ammo>0||state.hasReserve(),"Actual corridor ammunition exhausted");in=key(InputAction::Attack);wait=60;}
  }
  r.tick(in);fired+=std::max(0,ammo-state.magazine(weapon));if(n%1000==0){std::cout<<"G6-03 corridor n="<<n<<" alive="<<remaining(g).size()<<" HP="<<state.hp()<<" ammo="<<state.magazine(weapon)<<'\n';}
 }throw std::runtime_error("Actual corridor battle stalled");
}

