 if(optional){const int count=r.game.session().count(21),ammo=r.game.session().magazine(21),weapon=r.game.session().equipped(1);memorial(r);need(r.game.session().count(21)==count+1&&r.game.session().magazine(21)==ammo&&r.game.session().equipped(1)==weapon,"Memorial changed independent DE magazine/equipment");r.equip(21);r.closeMenu();r.move(Direction::Down);r.tick(key(InputAction::Weapon));for(int n=0;n<30;++n){r.tick();}need(r.game.raised(),"Natural DE raise absent");r.tick(key(InputAction::Attack));for(int n=0;n<140;++n){r.tick();}need(r.game.session().magazine(21)==ammo-1,"Natural DE shot did not consume original ammo");r.lower();memorialBack(r);r.receptionBack();originalSave(r,{8,7},3);r.reception();}
