 if(r.game.mapId()!=183){materialRoom(r);}const int countBefore=r.game.session().saveCount(),statBefore=r.game.session().variable(399);originalSave(r,{23,8},2,1);originalSave(r,{23,8},2,2);need(r.game.session().saveCount()==countBefore&&r.game.session().variable(399)==statBefore,"Cancelled natural save counted");originalSave(r,{23,8},2);need(r.game.session().saveCount()==countBefore+1&&r.game.session().variable(399)==statBefore+1,"Original save continuation counted incorrectly");auto disk=decodeSave(c,read(root/"slot-02.json"));need(disk.scene.map==183&&disk.continuation.statisticBefore==statBefore,"Natural M183 disk boundary differs");
 std::vector<std::string> expected;for(const auto& step:c.catalog.at("g6").at("alarm").at("steps")){if(step.contains("sound")){expected.push_back(readSound(step.at("sound")).resource);}}for(std::size_t n=0;n<voices.size();++n){need(voices[n]==expected[n%expected.size()],"Natural door/lift reset alarm cursor");}
 std::ofstream(root/"natural-result.json")<<Json{{"kind",optional?"real-G6-02-public-memorial-and-return-M183":"real-G6-02-public-main-return-M183"},{"runtime_injection",false},{"input_sha256",contentSha256(raw)},{"output_sha256",contentSha256(read(root/"slot-02.json"))},{"ticks",r.ticks},{"maps",r.maps},{"hp",r.game.session().hp()},{"magazine21",r.game.session().magazine(21)},{"count21",r.game.session().count(21)},{"save_count",r.game.session().saveCount()},{"initial_save_count",initial.saveCount},{"initial_hp",initial.hp},{"claim",r.game.session().flag(555)},{"alarm_submissions",voices.size()},{"message_groups",messages.size()}}.dump(2)<<'\n';std::cout<<"G6-03 natural public return/optional memorial/save PASS ticks="<<r.ticks<<'\n';
