void present(const CombatContent& c,const SaveSnapshot& disk,const std::filesystem::path& root){
 auto fixture=c;auto e=c.entries.at("post-pickup");GameSession source(c.items,disk.session,c.facts);finishSaveContinuation(source,disk);e.session=source.exportState();e.session.mainWeapon=20;e.map=163;e.playerTile={8,9};e.direction=Direction::Up;e.positions.clear();e.directions.clear();e.pages.clear();e.through.clear();fixture.entries["memorial-presentation-fixture"]=e;
 G2NaturalDriver r(fixture,root);DoraRender render(r.game,fixture,root/"frames");std::set<std::uint64_t> groups;int animationAge=-1,sounds=0;
 r.observe=[&](const PresentationEvent& event){render.pending.push_back(event);if(event.kind==PresentationEvent::Kind::Sound){++sounds;}if(event.kind==PresentationEvent::Kind::Cue&&fixture.cues.contains(event.id)){const auto& cue=fixture.cue(event.id);if(cue.at("kind")=="animation"&&cue.at("animation")=="32"){animationAge=0;}}};
 r.afterTick=[&]{render.tick();if(animationAge>=0&&++animationAge==5){render.frame("Animation32-original-cropped");}const auto& view=r.game.dialogue().view();if(r.game.dialogue().active()&&view.phase==DialoguePhase::AwaitingInput){groups.insert(view.request);const int last=view.lines.empty()?0:int(view.lines.back().size());render.frame("message-"+std::to_string(view.request)+"-lines-"+std::to_string(view.lines.size())+"-last-"+std::to_string(last));}};
 r.game.restartDevelopmentEntry("memorial-presentation-fixture");r.settle();r.tick(key());int manualStable=0;bool manualFrame=false;
 for(int n=0;n<2000;++n){if(r.game.foreground()==ForegroundKind::None&&!r.game.dialogue().active()){break;}const auto& v=r.game.dialogue().view();const bool manual=v.phase==DialoguePhase::Typing&&v.lines.size()==3&&v.lines[1]==U"「所以……"&&v.lines[2].empty();manualStable=manual?manualStable+1:0;InputFrame in;
  if(manualStable==12){render.frame("message4-original-manual-pause");manualFrame=true;std::cout<<"source C16 manual pause phase="<<int(v.phase)<<" request="<<v.request<<" ready_groups="<<groups.size()<<" stable_steps="<<manualStable<<'\n';in=key();manualStable=0;}
  else if(r.game.dialogue().active()&&v.phase==DialoguePhase::AwaitingInput){in=key();}r.tick(in);
  if(n==1999){const auto& held=r.game.dialogue().view();std::cerr<<"presentation timeout phase="<<int(held.phase)<<" request="<<held.request<<" ready_groups="<<groups.size()<<" last_line_width="<<(held.lines.empty()?0:held.lines.back().size())<<" foreground="<<int(r.game.foreground())<<'\n';throw std::runtime_error("Source presentation timed out");}}
 need(manualFrame,"Source manual pause was not observed");for(int n=0;n<120;++n){r.tick();}need(groups.size()==5&&r.game.session().flag(555)&&r.game.session().equipped(1)==20&&render.frames.contains("Animation32-original-cropped")&&sounds>0,"Source presentation groups/animation/audio missing");std::ofstream(root/"presentation-result.json")<<Json{{"kind","isolated-source-presentation-fixture-from-real02-facts-player-relocated163-mainWeapon20"},{"runtime_injection",true},{"natural_acceptance",false},{"five_ready_message_groups",groups.size()},{"grant_did_not_autoequip_DE",r.game.session().equipped(1)==20},{"frames",render.frames},{"sound_submissions_to_actual_backend",sounds},{"animation32_actual_frame",true}}.dump(2)<<'\n';std::cout<<"G6-03 five full source messages/manual pause/Animation32/SFML backend presentation fixture PASS\n";
}

