int main(int argc,char**argv){try{std::cout.setf(std::ios::unitbuf);need(argc==5||argc==6,"package actualSave isolatedRoot main|optional|visual|load|check [verifiedPrefix]");auto c=loadCombatContent(argv[1]);auto raw=read(argv[2]);auto saved=decodeSave(c,raw);std::filesystem::create_directories(argv[3]);const std::string mode=argv[4];if(mode=="check"){need(decodeSave(c,encodeSave(c,saved))==saved,"03 adaptation roundtrip failed");std::cout<<"G6-03 strict legacy adaptation/content PASS\n";}else if(mode=="rules"){rules(c,saved,raw,argv[3]);}else if(mode=="present"){present(c,saved,argv[3]);}else if(mode=="load"){load(c,raw,argv[3]);}else{natural(c,raw,argv[3],mode!="main",mode=="visual",argc==6?argv[5]:std::filesystem::path{});}return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
